insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$sao-bento-do-sapucai$q$, $q$https://camarasbs.sp.gov.br/Siscam/Documentos?handler=Arquivo&id=1013453 (Lei 2.108/2019) ; https://camarasbs.sp.gov.br/Siscam/Documentos?handler=Arquivo&id=1013792 (LC 2.128/2020)$q$, $q$Atos oficiais de São Bento do Sapucaí: domínio público (Lei 9.610/1998 art. 8º IV). Macrozona urbana aproximada: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Lei 2.108/2019, art. 1º (red. LC 2.128/2020): entrada, parada, estacionamento e circulação de veículos com PBT acima de 29 t ou comprimento acima de 17 m proibidos em todas as ruas da macrozona urbana do Plano Diretor, em qualquer dia ou hora. O ato não traz mapa: macrozona aproximada pela área urbana do Censo 2022 do distrito-sede, sem a SP-042 (Rod. Vereador Júlio da Silva) e a SP-050 (Rod. Monteiro Lobato).$q$);
